contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "deposit amount must be positive");
        require(address(this).balance >= depositAmount, "not enough balance to deposit");

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint256 contractBalanceBefore = address(c).balance;

        bool reverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 contractBalanceAfter = address(c).balance;
        bool refundSucceeded = !reverted;

        assert(
            (refundSucceeded && contractBalanceAfter == contractBalanceBefore - depositAmount) ||
            (!refundSucceeded && contractBalanceAfter == contractBalanceBefore)
        );
    }

    receive() external payable {}
}

